// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz the assertionId so the fuzzer can find any id where the mutant differs.
    function testFuzz_property(bytes32 assertionId) public {
        // The admissible domain is all bytes32, keep it wide (no vm.assume).

        // Call getAssertionPolicy and observe the returned struct's blockAssertion flag.
        bool ok;
        try c.getAssertionPolicy(assertionId) returns (EscalationManagerInterface.AssertionPolicy memory policy) {
            // In the reference implementation, blockAssertion is always false for any assertionId.
            ok = (policy.blockAssertion == false);
        } catch {
            // Should not revert in either reference or mutant; treat revert as violation of ok.
            ok = false;
        }

        // The single assertion: reference returns blockAssertion == false for all inputs,
        // while the mutant that set blockAssertion = true will fail this for some assertionId.
        assertTrue(ok);
    }
}

// Import the interface types needed for the returned struct type in the try/catch above.
interface EscalationManagerInterface {
    struct AssertionPolicy {
        bool blockAssertion;
        bool arbitrateViaEscalationManager;
        bool discardOracle;
        bool validateDisputers;
    }
}

