        EscalationManagerInterface_Proxy.AssertionPolicy memory policy = c.getAssertionPolicy(assertionId);
        // single assertion: blockAssertion must be false for all inputs on reference; mutant makes it true for some
        assertTrue(policy.blockAssertion == false);
