}

contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // single public test function: takes an assertionId and a disputeCaller
    // The rule: for any assertionId that is not the zero-bytes32, c.isDisputeAllowed(...) must be true.
    function check(bytes32 assertionId, address disputeCaller) public view {
        // require we are testing a non-zero assertionId to avoid trivial case
        require(assertionId != bytes32(0));

        // Observe the contract's response and assert it is true for all non-zero ids.
        bool allowed = c.isDisputeAllowed(assertionId, disputeCaller);
        assert(allowed);
    }

    // allow receiving ether if needed by caller setups
    receive() external payable {}
    fallback() external payable {}
}

