    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzzed inputs: identifier, time, and arbitrary ancillary data bytes
    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        // Keep domain wide: no restrictive assumptions. It's acceptable for ancillaryData to be empty.

        // We call getPrice via a try/catch on the public function to observe whether it returns successfully.
        bool ok;
        try c.getPrice(identifier, time, ancillaryData) returns (int256) {
