pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz the identifier so the fuzzer can find cases where int256(uint256(identifier)) differs
    // from the reference implementation's return. We call assertionDisputedCallback to drive the
    // public entry mentioned in the prompt (the reference's behaviour is that getPrice is a view
    // that does not deterministically return the truncated identifier; the mutant does return it).
    function testFuzz_property(bytes32 identifier) public {
        // Keep the domain wide; no assumptions.

        // Call the callback (must be from optimistic asserter address which we set to this contract in setUp)
